import type { ManagedProvider } from "./plugin";

export interface StartUrlOptions {
  /** Broker base for this environment, e.g. `https://api.runable.com/api/auth`. */
  issuer: string;
  applicationId: string;
  provider: ManagedProvider;
  /**
   * Delivery target the broker validates and redirects to with the token in the fragment: an https
   * origin (web) or a deep-link URI (native/desktop). Sent as `origin` — the wire name predates
   * non-origin targets.
   */
  redirectTarget: string;
  nonce: string;
  /** S256 PKCE challenge; the exchange then requires the matching verifier (native/desktop legs). */
  codeChallenge?: string;
}

export const buildStartUrl = (options: StartUrlOptions) => {
  const issuer = options.issuer.endsWith("/") ? options.issuer.slice(0, -1) : options.issuer;
  const url = new URL(`${issuer}/managed/start`);
  const params = new URLSearchParams({
    application_id: options.applicationId,
    provider: options.provider,
    origin: options.redirectTarget,
    nonce: options.nonce,
  });
  if (options.codeChallenge) params.set("code_challenge", options.codeChallenge);
  url.search = params.toString();
  return url.toString();
};
